var a=`0193-pistachio-gelato`;var t=`world-0193`;var n=`IT`;var s=`southern-europe`;var r=8;var c=231;var o={en:`Pistachio Gelato`,ua:`Фісташкове джелато`};var h={en:`A classic dish from Italy, featuring whole cow milk, heavy cream, pistachio paste, chicken egg. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: цільне коров'яче молоко, вершки високої жирності, фісташкова паста, куряче яйце. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var l=[{en:`Warm milk, cream and sugar until steaming but not boiling.`,ua:`Прогрійте молоко, вершки та цукор до появи пари, але не кип’ятіть.`,t:[`simmering`,`skimming-foam`],m:10,i:[[`whole-cow-milk`,600,`ml`],[`heavy-cream`,250,`ml`],[`white-granulated-sugar`,130,`g`]]},{en:`Whisk eggs with pistachio paste, temper gradually with the hot milk and return to low heat. Stir until custard reaches 82°C; strain and chill completely.`,ua:`Збийте яйця з фісташковою пастою, поступово введіть гаряче молоко для темперування й поверніть на малий вогонь. Помішуйте до 82°C, процідіть і повністю охолодіть.`,t:[`tempering-eggs`,`custard-stirring`],m:8,i:[[`pistachio-paste`,160,`g`],[`chicken-egg`,4,`pcs`]]},{en:`Stir in vanilla, churn the cold custard in an ice-cream machine and freeze until scoopable.`,ua:`Додайте ваніль, збийте холодну основу в морозивниці й заморозьте до консистенції для формування кульок.`,t:[`churning-ice-cream`,`freezing-food`],m:210,i:[[`vanilla-extract`,3,`ml`]]},{en:`Top each serving with chopped pistachios.`,ua:`Прикрасьте кожну порцію подрібненими фісташками.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pistachio`,40,`g`]]}];var g={slug:a,id:t,country:`IT`,region:s,servings:8,minutes:231,title:o,text:h,steps:l};export{n as country,g as default,t as id,c as minutes,s as region,r as servings,a as slug,l as steps,h as text,o as title};